struct NewsFeedItem: Codable {
    let headline: String
    let newsFeed: NewsFeed
}

struct NewsFeedResponse: Codable {
    let results: [NewsFeedItem]
}

class NewsAPI {
    static func fetchNews() async throws -> NewsFeedResponse {
        let url = "https://newsapi.org/v2/everything?q=apple&apiKey=YOUR_API_KEY"
        let url = URL(string: url)
        let data = try await URLSession.shared.data(from: url!)
        let newsFeedResponse = try JSONDecoder().decode(NewsFeedResponse.self, from: data)
        return newsFeedResponse
    }
}
